{
  "requirements": [
    {
      "text": "The system shall continuously monitor the health and integrity of all critical sensors and compute modules, and if any single‑point failure is detected it shall transition to a predefined safe‑stop state within a bounded distance."
    },
    {
      "text": "The system shall define an explicit Operational Design Domain (ODD) – including maximum speed, weather, illumination, and road‑type limits – and shall automatically disengage the automated driving mode whenever any ODD condition is violated."
    },
    {
      "text": "The system shall issue an unmistakable, multimodal takeover request (visual, auditory, and haptic) to the operator with a minimum lead time of 5 seconds, and shall only continue automated control if the operator acknowledges and assumes control within that interval."
    },
    {
      "text": "The system shall continuously assess driver attentiveness (e.g., hands on wheel, gaze direction) and, if the driver is inattentive and does not respond to a takeover request within the prescribed time, shall execute a safe‑stop maneuver."
    },
    {
      "text": "The system shall validate every planned trajectory in real time against the predicted occupancy of all tracked objects, applying a safety margin, and shall abort or re‑plan if any potential collision is detected."
    },
    {
      "text": "The system shall provide functional redundancy for all safety‑critical functions (perception, prediction, planning, and actuation) such that loss of any single component does not compromise safe operation."
    },
    {
      "text": "The system shall record, in a tamper‑evident log, all raw sensor data, perception outputs, predictions, planning decisions, control commands, and operator interventions with synchronized timestamps for post‑incident analysis."
    },
    {
      "text": "The system shall incorporate robust cybersecurity controls to prevent unauthorized remote access or modification of perception, planning, or control software and data."
    },
    {
      "text": "The system shall be capable of performing an emergency stop that brings the vehicle to a halt within a maximum of 5 meters from the point of detecting an imminent collision, regardless of operator input."
    },
    {
      "text": "The system shall undergo periodic safety validation (including software verification, hardware calibration, and sensor alignment) before each deployment, and shall refuse to operate if any validation step fails."
    }
  ]
}
